public void insert()
{
    next insert();
    this.metUpdateReceiptData();
}

public void update()
{
    next update();
    this.metUpdateReceiptData();
}

protected void metUpdateReceiptData()
{
    if(this.GrandParentRecId && this.OriginalMatched == false)
    {
        ttsbegin;
        VendInvoiceInfoLine vendInvoiceInfoLineforUpdate = VendInvoiceInfoLine::findRecId(this.GrandParentRecId, true);
        vendInvoiceInfoLineforUpdate.METReceiptedQuantity = this.PurchQty;
        vendInvoiceInfoLineforUpdate.METReceiptedCWQuantity = this.PdsCWQty;
        vendInvoiceInfoLineforUpdate.METReceiptedLineNetAmount = this.PurchQty * vendInvoiceInfoLineforUpdate.PurchPrice;
        vendInvoiceInfoLineforUpdate.doUpdate();
        ttscommit;
    }
}
